cat > build.py <<'PY'
import numpy as np
from math import sin,cos,pi
els=[]; xyz=[]; edges=[]
def atom(el,p):
 i=len(els);els.append(el);xyz.append(np.array(p,float));return i
def bond(i,j):edges.append((i,j))
def unit(a):return np.array(a)/np.linalg.norm(a)
def other_tetra(v1,v2):
 a=unit(v1);b=unit(v2);mid=unit(a+b);perp=unit(np.cross(a,b))
 c=1/(3*np.dot(a,mid));c=min(c,.85)
 return [-c*mid+np.sqrt(1-c*c)*perp,-c*mid-np.sqrt(1-c*c)*perp]
def methyl(p,parent):
 c=atom('C',p);bond(c,parent)
 axis=unit(xyz[parent]-xyz[c]);base=np.eye(3)[np.argmin(abs(axis))];u=unit(np.cross(axis,base));v=np.cross(axis,u)
 for j in range(3):
  a=2*pi*j/3+.3
  h=atom('H',xyz[c]+1.095*(-axis/3+np.sqrt(8/9)*(cos(a)*u+sin(a)*v)));bond(c,h)
 return c
T=atom('Ti',[0,0,0]);rings=[];sis=[]
for sign in [1,-1]:
 e=np.array([-cos(pi/18),0,-sign*sin(pi/18)]);y=np.array([0,1,0]);center=np.array([-.6,0,sign*2.02])
 ring=[]
 for j in range(5):
  phi=2*pi*j/5
  ring.append(atom('C',center+1.22*(cos(phi)*e+sin(phi)*y)))
 for j in range(5):bond(ring[j],ring[(j+1)%5])
 for j in range(1,5):methyl(center+2.72*(cos(2*pi*j/5)*e+sin(2*pi*j/5)*y),ring[j])
 si=atom('Si',xyz[ring[0]]+1.87*e);bond(ring[0],si);sis.append(si);rings+=ring
# ethylene between two Si
cs=[]
for i,s in enumerate(sis):
 sign=1 if i==0 else -1
 c=atom('C',xyz[s]+np.array([-.78,1.55,-sign*.713]));bond(s,c);cs.append(c)
bond(*cs)
for k,c in enumerate(cs):
 for d in other_tetra(xyz[sis[k]]-xyz[c],xyz[cs[1-k]]-xyz[c]):
  h=atom('H',xyz[c]+1.095*d);bond(c,h)
for k,s in enumerate(sis):
 for d in other_tetra(xyz[rings[5*k]]-xyz[s],xyz[cs[k]]-xyz[s]):methyl(xyz[s]+1.87*d,s)
me=methyl(np.array([2.13,0,0]),T)
with open('initial.xyz','w') as f:
 f.write(f'{len(els)}\nBis(tetramethylcyclopentadienyl) ansa-titanium(III) methyl; C25H43Si2Ti\n')
 for el,p in zip(els,xyz):f.write(f'{el:2} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
import json
json.dump({'rings':rings,'metal':T,'methyl':me,'bonds':edges,'Si':sis},open('topology.json','w'))
print('Atoms',len(els),'rings',rings,'Ti methyl',me,'Si',sis)
PY
