cat > relax.py <<'PY'
from rdkit import Chem
from rdkit.Chem import AllChem
import json,numpy as np
p=np.loadtxt('initial.xyz',skiprows=2,usecols=(1,2,3));el=[l.split()[0] for l in open('initial.xyz').readlines()[2:]];top=json.load(open('topology.json'));rings=top['rings'];r0=rings[:5];r1=rings[5:];cprings=[r0,r1]
keep=list(range(1,67));mp={j:i for i,j in enumerate(keep)}
rw=Chem.RWMol()
for j in keep:
 a=Chem.Atom(el[j])
 if j in rings:a.SetIsAromatic(True)
 if j in [rings[0],rings[5]]:a.SetFormalCharge(-1)
 rw.AddAtom(a)
for i,j in top['bonds']:
 if i not in mp or j not in mp:continue
 bt=Chem.BondType.AROMATIC if any(i in r and j in r for r in cprings) else Chem.BondType.SINGLE
 rw.AddBond(mp[i],mp[j],bt)
m=rw.GetMol();Chem.SanitizeMol(m)
c=Chem.Conformer(len(keep))
for i,j in enumerate(keep):c.SetAtomPosition(i,p[j])
m.AddConformer(c)
print('UFF params',AllChem.UFFHasAllMoleculeParams(m))
f=AllChem.UFFGetMoleculeForceField(m)
for j in rings:f.AddFixedPoint(mp[j])
f.Initialize();print('start',f.CalcEnergy());print('status',f.Minimize(maxIts=3000));print('end',f.CalcEnergy())
for i,j in enumerate(keep):p[j]=m.GetConformer().GetAtomPosition(i)
with open('preopt.xyz','w') as f:
 f.write('71\nUFF pre-relaxed titanium(III) complex\n')
 for e,x in zip(el,p):f.write(f'{e} {x[0]:.9f} {x[1]:.9f} {x[2]:.9f}\n')
